import { useQuery, UseQueryResult } from '@tanstack/react-query';
import { AxiosInstance } from 'axios';
import { environment } from '@castify/record-mv3/environment';
import { createBrowserLogger } from '@cfy/fe-monitoring';
import {
  USER_SETTINGS_QUERY_KEY,
  UserPersonalSettingKeys,
} from '../types/personalSettings';
import { useHttpClient } from './useHttpClient';
import { PersonalSettings } from '../types/personalSettings';

const logger = createBrowserLogger('usePersonalSettingsQueryValueByKey');

const getPersonalSettingsFactory =
  (httpClient: AxiosInstance) => async (): Promise<PersonalSettings> => {
    try {
      const url = `${environment.featuresServiceUrl}/personal-settings`;
      const response = await httpClient.get<PersonalSettings>(url);
      return response.data;
    } catch (error) {
      return { count: 0, items: [] };
    }
  };

export function usePersonalSettingsQuery(
  onSuccess: (newSettings: PersonalSettings | undefined) => void,
  onError: (error: Error) => void,
): UseQueryResult<PersonalSettings | undefined, unknown> {
  const httpClient = useHttpClient();

  return useQuery({
    queryKey: [USER_SETTINGS_QUERY_KEY],
    queryFn: getPersonalSettingsFactory(httpClient),
    onSuccess,
    onError,
  });
}

export const usePersonalSettingsQueryValueByKey = (
  keyName: UserPersonalSettingKeys,
) => {
  const result = usePersonalSettingsQuery(
    () => {},
    (error) => logger.error(error.message),
  );
  const extractKeyValue = (settings: PersonalSettings | undefined) => {
    return settings?.items?.find((item) => item?.name === keyName)?.value;
  };

  return {
    ...result,
    data: extractKeyValue(result.data),
    queryKey: [USER_SETTINGS_QUERY_KEY, keyName],
  };
};
