import { environment } from '@castify/record-mv3/environment';

const generateQueryParam = (ids: string[] = []): string => {
  if (ids.length === 0) return '';
  const encodedIds = encodeURIComponent(JSON.stringify({ ids }));
  return `?state=${encodedIds}`;
};

export const navigateToEditor = (ids: string[] = []) => {
  const url = `${environment.webAppUrl}/edit` + generateQueryParam(ids);
  window.open(url, '_blank');
};
