export const focusControllerTab = async () => {
  const controllerTabId = await chrome.tabs
    .query({
      url: `${globalThis.location.origin}/controller.html`,
    })
    .then((tabs) => tabs[0].id)
    .catch(() => null);
  if (!controllerTabId) return;
  chrome.tabs.update(controllerTabId, { active: true });
};
