import { useEffect, useState } from 'react';

const CONTAINER_CLASS = 'screencastify-google-drive';

interface InjectElementsOptions {
  isDisabled?: boolean;
}

export const useInjectGoogleDriveButton = ({
  isDisabled = false,
}: InjectElementsOptions): Element[] => {
  const [targets, setTargets] = useState<Element[]>([]);

  useEffect(() => {
    if (isDisabled) {
      document
        .querySelectorAll(`.${CONTAINER_CLASS}`)
        .forEach((el) => el.remove());
      setTargets([]);
      return;
    }

    const inject = () => {
      const newTargets: Element[] = [];

      const allMenuitems = Array.from(
        document.querySelectorAll('div[role="menuitem"]'),
      );

      const isFolderContext = allMenuitems.find((item) =>
        item.textContent?.trim().includes('Folder'),
      );
      if (isFolderContext) return;

      const openWithItemList = allMenuitems.filter((item) =>
        item.textContent?.trim().includes('Open with'),
      );
      const openWithItem = openWithItemList.at(-1);
      if (!openWithItem) {
        document
          .querySelectorAll(`.${CONTAINER_CLASS}`)
          .forEach((el) => el.remove());
        setTargets([]);
        return;
      }

      const parent = openWithItem.parentElement;
      const alreadyInjected = parent?.querySelector(`.${CONTAINER_CLASS}`);
      if (!parent || alreadyInjected) return;

      const container = document.createElement('div');
      container.className = CONTAINER_CLASS;
      container.style.display = 'flex';

      if (openWithItem.nextSibling) {
        parent.insertBefore(container, openWithItem.nextSibling);
      } else {
        parent.appendChild(container);
      }

      newTargets.push(container);

      if (newTargets.length > 0) {
        setTargets((prev) => [...prev, ...newTargets]);
      }
    };

    inject();

    const observer = new MutationObserver(() => {
      inject();
    });

    observer.observe(document.body, {
      childList: true,
      subtree: true,
    });

    return () => {
      observer.disconnect();
      setTargets([]);
    };
  }, [isDisabled]);

  return targets;
};
