import { createPortal } from 'react-dom';
import { useAuthStore } from '@castify/record-mv3/common/stores';
import { useInjectGoogleDriveButton } from './hooks/useInjectGoogleDriveButton';
import { GoogleDriveButton } from './GoogleDriveButton';
import { safeSendMessage } from '../content-safe-utils/safeSendMessage';
import { navigateToEditor } from './utils/navigateToEditor';
import { getSelectedIds } from './utils/getSelectedIds';

export const GoogleDriveController = () => {
  const isAuth = useAuthStore((s) => s.isAuth);

  const targets = useInjectGoogleDriveButton({});

  const handleClick = async () => {
    if (!isAuth) {
      safeSendMessage({ command: 'open-popup' });
      return;
    }

    const ids = getSelectedIds();
    navigateToEditor(ids);
  };

  return (
    <>
      {targets.map((target, idx) =>
        createPortal(
          <GoogleDriveButton onClick={handleClick} />,
          target,
          `screencastify-google-drive-${idx}`,
        ),
      )}
    </>
  );
};
