export const getSelectedIds = () => {
  const ids: string[] = [];
  // My Drive -> list / grid view
  const myDriveSelectedList = Array.from(
    document.querySelectorAll('div[aria-selected="true"][role="row"]'),
  ).map((el) => el.parentElement);

  myDriveSelectedList.forEach((el) => {
    if (el) ids.push(el.getAttribute('data-id') ?? '');
  });

  // Home -> list / grid view
  const homeSelectedList = document.querySelectorAll(
    'div[role="presentation"][data-target="doc"]',
  );
  homeSelectedList.forEach((el) => {
    const classLength = el.classList.length;
    if (
      classLength === 4 &&
      el.querySelector('div[data-list-item-target]')?.children.length !== 3
    ) {
      ids.push(el.getAttribute('data-id') ?? '');
    }
  });
  return ids;
};
