import { createRoot } from 'react-dom/client';
import { GoogleDriveController } from './GoogleDriveController';
import { GoogleDriveProviders } from './GoogleDriveProviders';

const CONTAINER_ID = 'screencastify-google-drive';

const injectScript = () => {
  if (document.getElementById(CONTAINER_ID)) return;

  const container = document.createElement('div');
  container.id = CONTAINER_ID;
  document.body.appendChild(container);

  const root = createRoot(container);
  root.render(
    <GoogleDriveProviders>
      <GoogleDriveController />
    </GoogleDriveProviders>,
  );
};

if (document.readyState === 'complete') {
  injectScript();
} else {
  window.addEventListener('load', injectScript);
}
