import { RecordingData, recordingIndexedDb } from './recording-indexed-db';
import { ServiceWorkerLogger } from '@cfy/fe-monitoring';
import { getFirebaseAccessToken } from '@castify/record-mv3/observability';
import {
  environment,
  getExtensionBrowserType,
} from '@castify/record-mv3/environment';

//This file gets loaded in both extension context and service worker context
//out of abundance of caution using service worker logger to avoid accidentally pulling in DOM deps
//and breaking the service worker
const currentVersion =
  chrome.runtime.getManifest().version_name + getExtensionBrowserType();
const logger = new ServiceWorkerLogger(
  environment.logServiceUrl,
  getFirebaseAccessToken,
  {
    appName: 'recording-data-manager',
    buildId: currentVersion,
  },
);

/**
 * Adds a recording segment to indexed db
 * @param recordingData
 */
export const addRecordingData = async (recordingData: RecordingData) => {
  try {
    recordingIndexedDb.recordingData.add(recordingData);
  } catch (error) {
    logger.error('error occurred while adding recording data', error);
  }
};

/**
 * This function will get all the recording segments for a video and sort them by
 * sequence number. This ensures we can stitch the segments back together as a webm.
 * Can potentially return an empty array which is bad and should be handled accordingly
 *
 * @param recordingId
 * @returns RecordingData[]
 */
export const getSortedRecordingSegments = async (recordingId: string) => {
  let data: RecordingData[] = [];
  try {
    data = await recordingIndexedDb.recordingData
      .where('recordingId')
      .equals(recordingId)
      .sortBy('sequenceNumber');
  } catch (error) {
    logger.error('error getting sorted recording segments', error);
  }
  return data;
};

type Range = {
  start?: number;
  end?: number;
};

export const getPartialRecordingSegments = async (
  recordingId: string,
  range?: Range,
) => {
  let data: RecordingData[] = [];
  try {
    data = await recordingIndexedDb.recordingData
      .where('[recordingId+segmentId]')
      .between(
        [recordingId, range?.start],
        [recordingId, range?.end],
        true,
        true,
      )
      .sortBy('[recordingId+segmentId]');
  } catch (error) {
    logger.error('error getting partial recording segments', error);
  }
  return data;
};

/**
 * Deletes the recording segments from indexed db for a given recording id
 * @param recordingId
 */
export const deleteRecordingDataById = async (recordingId: string) => {
  try {
    await recordingIndexedDb.recordingData
      .where('recordingId')
      .equals(recordingId)
      .delete();
  } catch (error) {
    logger.error('error deleting recording data by id', error);
  }
};

export const deleteRecordingDB = async () => {
  try {
    await recordingIndexedDb.delete();
  } catch (error) {
    logger.error('Error deleting recordingIndexed db', error);
  }
};
