import { Instance, types, getSnapshot, getParent } from 'mobx-state-tree';
import { ControllerStorageDriver } from '../controller/storage/ControllerStorageDriver';
import { IControllerState } from './controllerState.mst';
import {
  BitratePreset,
  CountInPreset,
  ResolutionPreset,
  FrameRatePreset,
  AUTO_STOP_OFF_VALUE,
  StorageLocation,
  RESOLUTION_PRESETS,
} from '@castify/record-mv3/common';
import { getChromeVersion } from '@cfy/fe-common';

const currentChromeVersion = getChromeVersion();

const RESOLUTIONS = types.enumeration('Resolution', [
  'OFF',
  '360p',
  '480p',
  '720p',
  '1080p',
  '4k',
]);

const FRAME_RATES = types.enumeration('FrameRate', [
  '1fps',
  '5fps',
  '10fps',
  '30fps',
  '60fps',
]);

const QUALITY_SETTINGS = types.enumeration('Bitrate', [
  'low',
  'medium',
  'high',
]);

export const RecordingSettings = types
  .model('RecordingSettings', {
    recordingType: types.optional(
      types.union(
        types.literal('tab'),
        types.literal('desktop'),
        types.literal('camera'),
      ),
      'tab',
    ),

    useAudioDevice: true,
    selectedAudioDeviceId: types.maybeNull(types.string),

    useVideoDevice: true,
    selectedVideoDeviceId: types.maybeNull(types.string),

    selectedResolution: types.optional(
      types.union(RESOLUTIONS, types.literal('OFF')),
      'OFF',
    ),
    selectedFrameRate: types.optional(FRAME_RATES, '30fps'),

    bitrate: types.optional(QUALITY_SETTINGS, 'medium'),
    useCountIn: true,
    countInDuration: types.optional(
      types.union(types.literal(3), types.literal(5), types.literal(10)),
      3,
    ),

    /** Boolean indicating whether or not to show the drawing tools during the recording */
    showDrawingTools: true,
    useAnnotationTools: false,
    useNoiseSuppression: false,
    useWatermark: false,
    recordMaxResolutionEnabled: false,

    // All pip related fields in this file represent
    // user preferences or if Pip will be used, they do NOT
    // represent if the camera is currently popped out
    pipEnabledWhenAvailable: currentChromeVersion >= 110 ? true : false,
    /** Time in minutes before the recording stops automatically */
    autoStopTime: types.optional(
      types.union(types.number),
      AUTO_STOP_OFF_VALUE,
    ),
    videoStorageLocation: types.optional(
      types.union(
        types.literal('google-drive'),
        types.literal('local-storage'),
      ),
      'google-drive',
    ),
    debugMode: types.optional(types.boolean, false),
  })
  .views((self) => {
    return {
      get pipEnabled(): boolean {
        return (
          self.recordingType === 'desktop' &&
          self.useVideoDevice &&
          self.pipEnabledWhenAvailable
        );
      },
      get isLocalStorageMode(): boolean {
        return self.videoStorageLocation === 'local-storage';
      },
      getSelectedResolution() {
        const resolutions = {
          '360p': { width: 640, height: 360 },
          '480p': { width: 854, height: 480 },
          '720p': { width: 1280, height: 720 },
          '1080p': { width: 1920, height: 1080 },
          '4k': { width: 4096, height: 2160 },
          // Note: Deprecated
          //
          // Using the window object is not 100% reliable due to a browser
          // optimization that prevents inactive tabs from getting the latest
          // window dimensions after resizing the window.
          // See https://issues.chromium.org/issues/40359414.
          //
          // This means that, when the controller tab calls this function, it will
          // return the dimensions it was at the last time it was active, rather than
          // the current dimensions of the active tab. This is an issue, because these
          // values will only be correct when you are recording the controller tab,
          // which is not the expected use-case.
          //
          // Given this, the RecordingManager was updated so that, instead of calling
          // this function to get the resolution when the value is OFF, it now grabs a
          // reference to the active tab and gets the resolution from there.
          OFF: {
            width: window.innerWidth,
            height: window.innerHeight,
          },
        };

        let { width, height } = resolutions[self.selectedResolution];
        if (
          self.selectedResolution === 'OFF' &&
          !self.recordMaxResolutionEnabled
        ) {
          width = Math.min(width, RESOLUTION_PRESETS['1080p'].width);
          height = Math.min(height, RESOLUTION_PRESETS['1080p'].height);
        }

        return { width, height };
      },
      getSelectedFrameRate() {
        return {
          '1fps': 1,
          '5fps': 5,
          '10fps': 10,
          '30fps': 30,
          '60fps': 60,
        }[self.selectedFrameRate];
      },
    };
  })
  .actions((self) => {
    return {
      async setRecordingType(value: 'tab' | 'desktop' | 'camera') {
        self.recordingType = value;
        await this.updateLocalStorage();
      },

      async setUseAudioDevice(value: boolean) {
        self.useAudioDevice = value;
        await this.updateLocalStorage();
      },

      async setSelectedAudioDeviceId(id: string) {
        self.selectedAudioDeviceId = id;
        await this.updateLocalStorage();
      },

      async setSelectedVideoDeviceId(id: string) {
        self.selectedVideoDeviceId = id;
        await this.updateLocalStorage();
      },

      // Update setting as well as send message to offscreen
      async setUseVideoDevice(value: boolean) {
        self.useVideoDevice = value;
        await this.updateLocalStorage();
        const parentState = getParent<IControllerState>(self);
        if (
          parentState.isRecording() &&
          self.pipEnabledWhenAvailable &&
          self.recordingType === 'desktop'
        ) {
          chrome.runtime.sendMessage({
            command: value ? 'VIDEO_ON' : 'VIDEO_OFF',
            payload: { deviceId: self.selectedVideoDeviceId },
            target: 'offscreen',
          });
        }
      },

      async setUseCountIn(value: boolean) {
        self.useCountIn = value;
        await this.updateLocalStorage();
      },

      async setCountInDuration(value: CountInPreset) {
        self.countInDuration = value;
        await this.updateLocalStorage();
      },

      async setUseAnnotationTools(value: boolean) {
        self.useAnnotationTools = value;
        await this.updateLocalStorage();
      },

      async setUseNoiseSuppression(value: boolean) {
        self.useNoiseSuppression = value;
        await this.updateLocalStorage();
      },

      async setUseWatermark(useWatermark: boolean) {
        self.useWatermark = useWatermark;
        await this.updateLocalStorage();
      },

      async setRecordMaxResolutionEnabled(recordMaxResolutionEnabled: boolean) {
        self.recordMaxResolutionEnabled = recordMaxResolutionEnabled;
        await this.updateLocalStorage();
      },

      async setSelectedResolution(resolution: ResolutionPreset | 'OFF') {
        self.selectedResolution = resolution;
        this.updateLocalStorage();
      },
      async setSelectedFrameRate(frameRate: FrameRatePreset) {
        self.selectedFrameRate = frameRate;
        this.updateLocalStorage();
      },
      async setPipEnabled(value: boolean) {
        self.pipEnabledWhenAvailable = value;
        await this.updateLocalStorage();
      },
      async setShowDrawingTools(value: boolean) {
        self.showDrawingTools = value;
        await this.updateLocalStorage();
      },
      async setBitrate(bitrate: BitratePreset) {
        self.bitrate = bitrate;
        await this.updateLocalStorage();
      },
      async setAutoStopTime(value: number) {
        self.autoStopTime = value;
        await this.updateLocalStorage();
      },
      async setVideoStorageLocation(value: StorageLocation) {
        self.videoStorageLocation = value;
        await this.updateLocalStorage();
      },
      async toggleDebugMode() {
        self.debugMode = !self.debugMode;
        await this.updateLocalStorage();
      },
      async updateLocalStorage() {
        await ControllerStorageDriver.replaceRecordingSettings(
          getSnapshot(self),
        );
      },
    };
  });
export type IRecordingSettings = Instance<typeof RecordingSettings>;
