import { useEffect, useState } from 'react';
import { getFflagNoCache } from './getFflagNoCache';

export const useHomePageEnabledFflag = () => {
  const [isHomePageEnabled, setIsHomePageEnabled] = useState(false);

  useEffect(() => {
    const fetchFlag = async () => {
      const flagValue = await getFflagNoCache('homePageEnabled');
      setIsHomePageEnabled(flagValue);
    };

    fetchFlag();
  }, []);

  return isHomePageEnabled;
};
