import { usePendoStore } from '@castify/record-mv3/common/stores';
import { PropsWithChildren, useEffect } from 'react';
import { isExtensionActive } from '../content-scripts/content-safe-utils/isExtensionActive';
import { getPendoMsgFromEvent } from './getPendoMsgFromEvent';

export const PendoEventBridgeStore = ({ children }: PropsWithChildren) => {
  const queueEvent = usePendoStore((s) => s.queueEvent);

  useEffect(() => {
    const handleClick = (event: MouseEvent) => {
      if (!isExtensionActive()) return;
      const { eventName, additionalData } = getPendoMsgFromEvent(event);
      if (!eventName) return;

      queueEvent({ eventName, additionalData });
    };

    window.addEventListener('click', handleClick, true);
    return () => {
      window.removeEventListener('click', handleClick, true);
    };
  }, [queueEvent]);

  return <>{children}</>;
};
