export const safeSendMessage = <T, R = unknown>(
  message: T,
): Promise<R | null> => {
  return new Promise((resolve) => {
    if (!chrome?.runtime?.id) {
      return resolve(null);
    }

    try {
      chrome.runtime.sendMessage(message, (response) => {
        if (chrome.runtime.lastError) {
          return resolve(null);
        }
        resolve(response);
      });
    } catch (err) {
      resolve(null);
    }
  });
};
